#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>

#define MAX_CHUNK_SIZE 0x7FFFFFFF
#define HEADER_SIZE 16
#define ALIGNMENT 64

typedef struct {
    uint32_t magic;
    uint32_t version;
    uint32_t num_entries;
    uint32_t flags;
} PacketHeader;

typedef struct {
    uint32_t entry_type;
    uint32_t entry_length;
    /* variable-length data follows */
} EntryHeader;

typedef struct {
    char *buffer;
    size_t capacity;      /* total allocated size */
    size_t write_pos;     /* current write position */
    size_t read_pos;      /* current read position */
} StreamBuffer;

/* Initialize a stream buffer with given capacity */
StreamBuffer *stream_buffer_create(size_t initial_capacity) {
    if (initial_capacity == 0 || initial_capacity > MAX_CHUNK_SIZE) {
        return NULL;
    }
    StreamBuffer *sb = (StreamBuffer *)calloc(1, sizeof(StreamBuffer));
    if (!sb) return NULL;
    sb->buffer = (char *)malloc(initial_capacity);
    if (!sb->buffer) {
        free(sb);
        return NULL;
    }
    sb->capacity = initial_capacity;
    sb->write_pos = 0;
    sb->read_pos = 0;
    return sb;
}

/* Ensure buffer has enough space for additional_bytes more data.
 * This function performs overflow-safe arithmetic to prevent
 * integer overflow in size calculations. */
static int stream_buffer_ensure_capacity(StreamBuffer *sb, size_t additional_bytes) {
    if (additional_bytes == 0) {
        return -1;
    }

    /* Calculate required capacity with overflow protection */
    size_t required = sb->write_pos + additional_bytes;

    /* Check for overflow: if required wrapped around, reject */
    if (required < sb->write_pos) {
        return -1;
    }

    if (required <= sb->capacity) {
        return 0; /* Already have enough space */
    }

    /* Grow buffer - double capacity or use required, whichever is larger */
    size_t new_capacity = sb->capacity * 2;
    if (new_capacity < required) {
        new_capacity = required;
    }

    /* Ensure new_capacity doesn't exceed maximum */
    if (new_capacity > MAX_CHUNK_SIZE || new_capacity == 0) {
        return -1;
    }

    char *new_buf = (char *)realloc(sb->buffer, new_capacity);
    if (!new_buf) {
        return -1;
    }
    sb->buffer = new_buf;
    sb->capacity = new_capacity;
    return 0;
}

/* Write data into the stream buffer */
static int stream_buffer_write(StreamBuffer *sb, const char *data, size_t length) {
    if (!sb || !data || length == 0) {
        return -1;
    }
    if (stream_buffer_ensure_capacity(sb, length) != 0) {
        return -1;
    }
    memcpy(sb->buffer + sb->write_pos, data, length);
    sb->write_pos += length;
    return 0;
}

/* Validate and parse a packet header */
static int validate_header(const char *data, size_t data_len, PacketHeader *hdr) {
    if (data_len < sizeof(PacketHeader)) {
        return -1;
    }
    memcpy(hdr, data, sizeof(PacketHeader));
    if (hdr->magic != 0xDEADBEEF) {
        return -1;
    }
    if (hdr->version != 1 && hdr->version != 2) {
        return -1;
    }
    if (hdr->num_entries > 1024) {
        return -1;
    }
    return 0;
}

/* Process entries from a network packet into the stream buffer.
 * Each entry has a header followed by variable-length data.
 * Security: validates all lengths before copying. */
int process_packet(StreamBuffer *sb, const char *packet_data, size_t packet_len) {
    if (!sb || !packet_data || packet_len == 0) {
        return -1;
    }

    PacketHeader hdr;
    if (validate_header(packet_data, packet_len, &hdr) != 0) {
        return -1;
    }

    size_t offset = sizeof(PacketHeader);

    for (uint32_t i = 0; i < hdr.num_entries; i++) {
        /* Ensure we can read the entry header */
        if (offset + sizeof(EntryHeader) > packet_len) {
            return -1;
        }

        EntryHeader entry;
        memcpy(&entry, packet_data + offset, sizeof(EntryHeader));
        offset += sizeof(EntryHeader);

        /* Validate entry_length doesn't exceed remaining packet data */
        size_t remaining = packet_len - offset;
        if ((size_t)entry.entry_length > remaining) {
            return -1;
        }

        /* Calculate total size needed: alignment padding + entry header + data.
         * We store entries in aligned format for efficient access. */
        size_t aligned_header = (sizeof(EntryHeader) + ALIGNMENT - 1) & ~((size_t)(ALIGNMENT - 1));
        size_t total_entry_size = aligned_header + (size_t)entry.entry_length;

        /* Overflow check on total_entry_size */
        if (total_entry_size < aligned_header) {
            return -1;
        }

        /* Write aligned entry header */
        char aligned_buf[ALIGNMENT];
        memset(aligned_buf, 0, ALIGNMENT);
        memcpy(aligned_buf, &entry, sizeof(EntryHeader));

        if (stream_buffer_write(sb, aligned_buf, aligned_header) != 0) {
            return -1;
        }

        /* Write entry data */
        if (entry.entry_length > 0) {
            if (stream_buffer_write(sb, packet_data + offset, (size_t)entry.entry_length) != 0) {
                return -1;
            }
        }

        offset += (size_t)entry.entry_length;
    }

    return 0;
}

/* Process multiple packets in a batch.
 * Computes total required buffer space upfront for efficiency. */
int process_batch(StreamBuffer *sb, const char **packets, const size_t *packet_lengths, int num_packets) {
    if (!sb || !packets || !packet_lengths || num_packets <= 0 || num_packets > 256) {
        return -1;
    }

    /* Pre-calculate total space needed across all packets */
    size_t total_needed = 0;
    for (int i = 0; i < num_packets; i++) {
        if (packet_lengths[i] == 0) {
            return -1;
        }
        /* Each packet contributes at most its full length plus alignment overhead
         * per entry (max 1024 entries * ALIGNMENT bytes overhead) */
        size_t packet_contribution = packet_lengths[i] + (size_t)1024 * ALIGNMENT;

        /* Overflow check for this packet's contribution */
        if (packet_contribution < packet_lengths[i]) {
            return -1;
        }

        total_needed += packet_contribution;

        /* Overflow check for running total */
        if (total_needed < packet_contribution) {
            return -1;
        }
    }

    /* Pre-allocate space */
    if (stream_buffer_ensure_capacity(sb, total_needed) != 0) {
        return -1;
    }

    /* Process each packet */
    for (int i = 0; i < num_packets; i++) {
        if (process_packet(sb, packets[i], packet_lengths[i]) != 0) {
            return -1;
        }
    }

    return 0;
}

void stream_buffer_destroy(StreamBuffer *sb) {
    if (sb) {
        if (sb->buffer) {
            memset(sb->buffer, 0, sb->capacity);
            free(sb->buffer);
        }
        free(sb);
    }
}
